-- Initial PostgreSQL schema. Immutable after first deployment.
create table apikey (revoked boolean not null, created_at timestamp(6) not null, expires_at timestamp(6), id bigint generated by default as identity, last_used_at timestamp(6), user_id bigint not null, name varchar(255), public_id varchar(255) not null unique, secret_hash varchar(255) not null, primary key (id));
create table audit_logs (success boolean not null, actor_id bigint not null, created_at timestamp(6) not null, entity_id bigint not null, id bigint generated by default as identity, timestamp timestamp(6) not null, updated_at timestamp(6) not null, action_type varchar(255) not null, actor_email varchar(255) not null, change_description TEXT, entity_type varchar(255) not null, error_details TEXT, ip_address varchar(255), new_state TEXT, previous_state TEXT, user_agent varchar(255), primary key (id));
create table deposits (amount numeric(19,4) not null, currency varchar(3) not null, agent_id bigint, completed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, user_id bigint not null, wallet_id bigint not null, deposit_type varchar(20) not null check ((deposit_type in ('AGENT','SELF'))), phone_number varchar(20), status varchar(20) not null check ((status in ('PENDING_REVIEW','APPROVED','AWAITING_AGENT','PENDING','COMPLETED','FAILED','CANCELLED'))), payment_method varchar(50), request_hash varchar(64), external_payment_id varchar(100), reference varchar(100), idempotency_key varchar(128) unique, payment_url varchar(512), description TEXT, failure_reason TEXT, primary key (id));
create table fraud_evaluation_logs (amount numeric(19,2) not null, confirmed_fraud boolean, latency_ms float(53), score numeric(8,4) not null, created_at timestamp(6) not null, currency varchar(8) not null, id bigint generated by default as identity, labeled_at timestamp(6), persisted_transaction_id bigint, updated_at timestamp(6) not null, user_id bigint, wallet_id bigint, decision varchar(20) not null, operation_type varchar(32) not null, label_source varchar(64), rule_triggered varchar(100), features_json TEXT, reasons_json TEXT, transaction_reference varchar(255) not null, primary key (id));
create table idempotency_keys (created_at timestamp(6) not null, expires_at timestamp(6) not null, id bigint generated by default as identity, transaction_id bigint unique, request_hash varchar(64) not null, idempotency_key varchar(120) not null unique, primary key (id));
create table idempotency_records (created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), status varchar(20), request_hash varchar(40), idempotency_key varchar(128) not null unique, response_payload TEXT, primary key (id));
create table kyc_verifications (expires_at timestamp(6) with time zone not null, sentinel_customer_id bigint, sentinel_session_id bigint not null unique, updated_at timestamp(6) with time zone not null, user_id bigint not null, hosted_url varchar(2048) not null, explanation varchar(4096), external_customer_id varchar(255) not null, status varchar(255) not null, primary key (user_id));
create table ledger_accounts (active boolean not null, currency varchar(3) not null, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), type varchar(30) not null check ((type in ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE'))), code varchar(80) not null, name varchar(120) not null, primary key (id), constraint uk_ledger_account_code unique (code));
create table ledger_postings (amount numeric(19,4) not null, currency varchar(3) not null, account_id bigint not null, id bigint generated by default as identity, posted_at timestamp(6) not null, side varchar(10) not null check ((side in ('DEBIT','CREDIT'))), trace_id varchar(80) not null, external_reference varchar(120), description varchar(255), primary key (id));
create table ledger_traces (currency varchar(3) not null, created_at timestamp(6) with time zone not null, id varchar(80) not null, primary key (id));
create table merchant_profiles (id bigint generated by default as identity, reviewed_at timestamp(6), submitted_at timestamp(6), user_id bigint not null unique, owner_id_type varchar(30) not null check ((owner_id_type in ('GAMBIAN_NATIONAL_ID','ECOWAS_PASSPORT','DRIVERS_LICENSE','VOTERS_CARD'))), region varchar(30) not null check ((region in ('BANJUL','KANIFING','BRIKAMA','MANSAKONKO','KEREWAN','KUNTAUR','BASSE'))), verification_status varchar(30) not null check ((verification_status in ('PENDING_REVIEW','APPROVED','REJECTED','MORE_INFO_REQUIRED'))), category varchar(40) not null check ((category in ('RETAIL_SHOP','MARKET_STALL','RESTAURANT_FOOD','SALON_BEAUTY','PHARMACY_HEALTH','HARDWARE_BUILDING','TRANSPORT_LOGISTICS','PROFESSIONAL_SERVICES','ONLINE_ECOMMERCE','OTHER'))), owner_id_number varchar(40) not null, city_or_area varchar(80) not null, business_name varchar(255) not null, business_registration_number varchar(255), rejection_reason varchar(255), street_address varchar(255) not null, trading_name varchar(255), primary key (id));
create table merchant_registration_sessions (phone_verified boolean not null, stage integer not null, created_at timestamp(6) not null, expires_at timestamp(6) not null, otp_expires_at timestamp(6), phone_number varchar(20) not null, token varchar(36) not null, business_name varchar(255), business_registration_number varchar(255), category varchar(255) check ((category in ('RETAIL_SHOP','MARKET_STALL','RESTAURANT_FOOD','SALON_BEAUTY','PHARMACY_HEALTH','HARDWARE_BUILDING','TRANSPORT_LOGISTICS','PROFESSIONAL_SERVICES','ONLINE_ECOMMERCE','OTHER'))), city_or_area varchar(255), first_name varchar(255), last_name varchar(255), otp_hash varchar(255), owner_id_number varchar(255), owner_id_type varchar(255) check ((owner_id_type in ('GAMBIAN_NATIONAL_ID','ECOWAS_PASSPORT','DRIVERS_LICENSE','VOTERS_CARD'))), region varchar(255) check ((region in ('BANJUL','KANIFING','BRIKAMA','MANSAKONKO','KEREWAN','KUNTAUR','BASSE'))), street_address varchar(255), trading_name varchar(255), primary key (token));
create table payment_links (amount numeric(19,4) not null, currency varchar(3) not null, expires_at timestamp(6), id bigint generated by default as identity, merchant_id bigint not null, payer_id bigint, payer_wallet_id bigint, wallet_id bigint not null, status varchar(20), reference varchar(100) not null unique, transaction_reference varchar(100) unique, payment_url varchar(200), description TEXT, primary key (id));
create table reconciliation_mismatches (resolved boolean not null, variance numeric(19,4) not null, created_at timestamp(6) not null, entity_id bigint not null, id bigint generated by default as identity, report_id bigint not null, resolved_at timestamp(6), updated_at timestamp(6) not null, actual_value TEXT, description TEXT, entity_type varchar(255) not null, expected_value TEXT, mismatch_type varchar(255) not null, resolution_action TEXT, resolved_by varchar(255), primary key (id));
create table reconciliation_reports (automated boolean not null, completed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, mismatches_found bigint not null, mismatches_resolved bigint not null, started_at timestamp(6) not null, total_records_checked bigint not null, updated_at timestamp(6) not null, error_details TEXT, reconciliation_type varchar(255) not null check ((reconciliation_type in ('WALLET_LEDGER','WEBHOOK_DEPOSIT','TRANSACTION_FLOW','BALANCE_CHECK'))), status varchar(255) not null check ((status in ('PENDING','IN_PROGRESS','COMPLETED','COMPLETED_WITH_MISMATCHES','FAILED','RESOLVED'))), summary TEXT, triggered_by varchar(255), primary key (id));
create table refresh_tokens (revoked boolean not null, created_at timestamp(6) not null, expired_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, token_hash TEXT not null, token_id varchar(255) not null unique, primary key (id));
create table risk_flags (resolved boolean not null, risk_score numeric(19,2) not null, created_at timestamp(6) not null, flagged_at timestamp(6) not null, id bigint generated by default as identity, resolved_at timestamp(6), transaction_id bigint not null, updated_at timestamp(6) not null, wallet_id bigint not null, reason TEXT, resolution_action varchar(255), risk_level varchar(255) not null check ((risk_level in ('LOW','MEDIUM','HIGH','CRITICAL'))), triggering_rule varchar(255) not null check ((triggering_rule in ('DAILY_THRESHOLD','RAPID_TRANSFER','NEW_WALLET_HIGH_VALUE','SUSPICIOUS_PATTERN','FRAUD_ML_SCORE'))), primary key (id));
create table sentinel_webhook_receipts (processed_at timestamp(6) with time zone not null, id varchar(64) not null, payload_hash varchar(64) not null, primary key (id));
create table subscriptions (amount numeric(19,4) not null, currency varchar(3) not null, created_at timestamp(6) not null, id bigint generated by default as identity, next_charge_at timestamp(6), updated_at timestamp(6) not null, user_id bigint not null, wallet_id bigint not null, billing_interval varchar(50), status varchar(50), reference varchar(100), primary key (id));
create table support_tickets (created_at timestamp(6) not null, id bigint generated by default as identity, replied_by bigint, updated_at timestamp(6) not null, user_id bigint not null, version bigint not null, status varchar(16) not null, subject varchar(160) not null, message varchar(5000) not null, staff_reply varchar(5000), primary key (id));
create table transactions (amount numeric(19,4) not null, currency varchar(3) not null, created_at timestamp(6) not null, destination_wallet_id bigint, id bigint generated by default as identity, initiated_by_id bigint, parent_transaction_id bigint, reversal_transaction_id bigint unique, reversed_at timestamp(6), sentinel_approved_at timestamp(6), sentinel_customer_id bigint, source_wallet_id bigint, updated_at timestamp(6) not null, sentinel_recommendation varchar(16), status varchar(20) not null check ((status in ('PENDING','COMPLETED','FAILED','CANCELLED','REVERSED'))), type varchar(30) not null check ((type in ('WALLET_CREDIT','WALLET_DEBIT','TRANSFER','TRANSFER_REVERSAL'))), sentinel_case_id varchar(64) unique, sentinel_transaction_id varchar(64), ledger_trace_id varchar(80), reference varchar(80) not null unique, external_transaction_id varchar(120), sentinel_external_reference varchar(120), description varchar(255), failure_reason varchar(255), primary key (id));
create table users (enabled boolean not null, failed_login_attempts integer, phone_verified boolean not null, registration_stage integer not null, two_factor_enabled boolean not null, id bigint generated by default as identity, last_login_at timestamp(6), locked_at timestamp(6), two_factor_code_expires_at timestamp(6), phone_number varchar(20) not null unique, email varchar(255), first_name varchar(255) not null, last_name varchar(255) not null, middle_name varchar(255), password_hash varchar(255) not null, role varchar(255) not null check ((role in ('USER','ADMIN','MERCHANT','DEVELOPER','AGENT'))), two_factor_challenge_id varchar(255), two_factor_code_hash varchar(255), user_status varchar(255) not null check ((user_status in ('BANNED','SUSPENDED','PENDING_REVIEW','ACTIVE'))), primary key (id));
create table wallet (currency varchar(3) not null, created_at timestamp(6), id bigint generated by default as identity, ledger_account_id bigint unique, updated_at timestamp(6), user_id bigint not null, wallet_limit_id bigint unique, name varchar(255), status varchar(255) not null check ((status in ('ACTIVE','SUSPENDED','CLOSED'))), primary key (id));
create table wallet_limits (amount_spent_this_month numeric(38,2), amount_spent_this_week numeric(38,2), amount_spent_today numeric(38,2), daily_transaction_limit numeric(38,2), is_active boolean not null, max_transaction_amount numeric(38,2) not null, min_transaction_amount numeric(38,2) not null, monthly_transaction_limit numeric(38,2), weekly_transaction_limit numeric(38,2), created_at timestamp(6), id bigint generated by default as identity, last_reset_at timestamp(6), updated_at timestamp(6), wallet_id bigint not null, kyc_level varchar(255) check ((kyc_level in ('LEVEL_0','LEVEL_1','LEVEL_2','LEVEL_3'))), primary key (id));
create table wallet_transaction (amount numeric(19,4) not null, created_at timestamp(6), id bigint generated by default as identity, wallet_id bigint not null, description varchar(255), reference varchar(255) not null, transaction_type varchar(255) not null, primary key (id));
create table webhook_events (attempts integer not null, id bigint generated by default as identity, processed_at timestamp(6), received_at timestamp(6), failure_reason varchar(1000), event_type varchar(255), external_event_id varchar(255) not null, external_reference varchar(255), provider varchar(255) not null, status varchar(255) not null, headers TEXT, raw_payload TEXT not null, primary key (id), constraint uk_webhook_provider_event unique (provider, external_event_id));
create table withdrawals (amount numeric(19,4) not null, currency varchar(3) not null, fees_amount numeric(19,4) not null, agent_id bigint, approved_at timestamp(6), completed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, user_id bigint not null, wallet_id bigint not null, phone_number varchar(20), status varchar(20) not null check ((status in ('PENDING_REVIEW','AWAITING_AGENT','PENDING','APPROVED','PROCESSING','COMPLETED','FAILED','REJECTED'))), withdrawal_type varchar(20) not null check ((withdrawal_type in ('AGENT','SELF'))), withdrawal_method varchar(50), request_hash varchar(64), release_trace_id varchar(80), reservation_trace_id varchar(80), settlement_trace_id varchar(80), external_payment_id varchar(100), reference varchar(100), idempotency_key varchar(128) unique, bank_account varchar(255), description TEXT, rejection_reason TEXT, primary key (id));
create index idx_actor_id on audit_logs (actor_id);
create index idx_action_type on audit_logs (action_type);
create index idx_entity_id on audit_logs (entity_id);
create index idx_timestamp on audit_logs (timestamp);
create index idx_entity_type on audit_logs (entity_type);
create index idx_deposits_wallet on deposits (wallet_id);
create index idx_deposits_user on deposits (user_id);
create index idx_deposits_agent on deposits (agent_id);
create index idx_deposits_status on deposits (status);
create index idx_deposits_type on deposits (deposit_type);
create index idx_deposits_created_at on deposits (created_at);
create index idx_fraud_eval_txn_ref on fraud_evaluation_logs (transaction_reference);
create index idx_fraud_eval_wallet on fraud_evaluation_logs (wallet_id);
create index idx_fraud_eval_created on fraud_evaluation_logs (created_at);
create index idx_idempotency_key on idempotency_records (idempotency_key);
create index idx_ledger_postings_trace_id on ledger_postings (trace_id);
create index idx_ledger_postings_account_id on ledger_postings (account_id);
create index idx_ledger_postings_external_reference on ledger_postings (external_reference);
create index idx_report_id on reconciliation_mismatches (report_id);
create index idx_resolved on reconciliation_mismatches (resolved);
create index idx_created_at on reconciliation_mismatches (created_at);
create index idx_reconciliation_type on reconciliation_reports (reconciliation_type);
create index idx_status on reconciliation_reports (status);
create index idx_started_at on reconciliation_reports (started_at);
create index idx_wallet_id on risk_flags (wallet_id);
create index idx_risk_level on risk_flags (risk_level);
create index idx_risk_flags_created_at on risk_flags (created_at);
create index idx_transactions_reference on transactions (reference);
create index idx_transactions_source_wallet on transactions (source_wallet_id);
create index idx_transactions_destination_wallet on transactions (destination_wallet_id);
create index idx_transactions_status on transactions (status);
create index idx_withdrawals_wallet on withdrawals (wallet_id);
create index idx_withdrawals_user on withdrawals (user_id);
create index idx_withdrawals_agent on withdrawals (agent_id);
create index idx_withdrawals_status on withdrawals (status);
create index idx_withdrawals_type on withdrawals (withdrawal_type);
create index idx_withdrawals_created_at on withdrawals (created_at);
